// AUTO-GENERATED controller artwork (user-provided PNGs from build_assets/controllers),
// embedded as data URIs so they need no external file / path resolution inside the
// bundled launcher. They are drawn as CSS MASKS (backgroundColor: currentColor) - the
// PNGs are solid black, so an <img> would be black-on-black; as a mask each pad still
// takes its accent color (PS blue / Xbox green), exactly like the old inline SVGs.
export const CONTROLLER_IMG = {
  ps5:  'data:image/png;base64,',
  ps4:  'data:image/png;base64,',
  xbox: 'data:image/png;base64,',
} as const;
